    # Insert hyphens before uppercase letters (camelCase -> kebab-case)
    result = []
    for i, c in enumerate(s):
        if c.isupper() and i > 0:
            result.append('-')
        result.append(c.lower())
    # Replace remaining underscores with hyphens
    result = ''.join(result).replace('_', '-')
    # Collapse double hyphens
    while '--' in result:
