function eq(a, b) {
  // Handle primitives and same-reference cases
  if (a === b) return true;

  // Handle null/undefined (typeof null === 'object')
  if (a == null || b == null) return false;

  // Both must be objects (including arrays) to continue
  const typeA = typeof a;
  const typeB = typeof b;
  if (typeA !== typeB) return false;
  if (typeA !== 'object') return false;

  // Handle Arrays - compare length then elements
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!eq(a[i], b[i])) return false;
    }
    return true;
  }

  // Handle plain objects - compare own/enumerable properties
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (const key of keysA) {
    if (!Object.prototype.hasOwnProperty.call(b, key)) return false;
    if (!eq(a[key], b[key])) return false;
  }
