def majority(xs):
    """Return the majority element of xs (appears > half the time).
    Uses the Boyer-Moore majority vote algorithm: O(n) time, O(1) space."""
    candidate = None
    count = 0
    for x in xs:
        if count == 0:
            candidate = x
        count += (1 if x == candidate else -1)
    return candidate

def spiral(m):
    if not m:
