def can_finish(n, prereqs):
    # Build adjacency list: course -> list of courses that depend on it
    # prereq [a, b] means b -> a (b must be taken before a)
    graph = [[] for _ in range(n)]
    for a, b in prereqs:
        graph[b].append(a)

    # 0 = unvisited, 1 = in progress (visiting), 2 = done
    state = [0] * n

    def dfs(course):
        if state[course] == 2:
            return True  # already verified no cycle from this node
        if state[course] == 1:
            return False  # cycle detected
        state[course] = 1  # mark as visiting
        for next_course in graph[course]:
