def spiral(m):
    if not m:
        return []
    rows, cols = len(m), len(m[0])
    top, bottom = 0, rows - 1
    left, right = 0, cols - 1
    result = []
    while top <= bottom and left <= right:
        # Traverse right across top row
        for c in range(left, right + 1):
            result.append(m[top][c])
        top += 1
        # Traverse down right column
        for r in range(top, bottom + 1):
            result.append(m[r][right])
        right -= 1
        # Traverse left across bottom row (if still within bounds)
        if top <= bottom:
            for c in range(right, left - 1, -1):
                result.append(m[bottom][c])
            bottom -= 1
        # Traverse up left column (if still within bounds)
        if left <= right:
            for r in range(bottom, top - 1, -1):
                result.append(m[r][left])
            left += 1
    return result

