    """Parse a single CSV line, respecting double-quoted fields."""
    fields = []
    i = 0
    current = ''
    in_quotes = False

    while i < len(line):
        ch = line[i]
        if in_quotes:
            if ch == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    current += '"'
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                current += ch
                i += 1
        else:
            if ch == '"':
                if current:
                    fields.append(current)
                    current = ''
                in_quotes = True
                i += 1
            elif ch == ',':
                fields.append(current)
                current = ''
                i += 1
            else:
                current += ch
                i += 1

    fields.append(current)
    return fields

