def can_finish(n, prereqs):
    # Build adjacency list: course -> list of prerequisites
    graph = [[] for _ in range(n)]
    for course, prereq in prereqs:
        graph[course].append(prereq)

    # 0 = unvisited, 1 = in progress (gray), 2 = done (black)
    state = [0] * n

    def dfs(course):
        if state[course] == 2:
            return True  # already processed, no cycle from here
        if state[course] == 1:
            return False  # cycle detected
        state[course] = 1  # mark as in progress
        for prereq in graph[course]:
            if not dfs(prereq):
                return False
        state[course] = 2  # mark as done
        return True

    for course in range(n):
        if state[course] == 0:
            if not dfs(course):
                return False
    return True

