def can_finish(n, prereqs):
    # Build adjacency list: course -> list of prerequisites
    # prereq [a, b] means course a depends on course b (b -> a edge)
    graph = [[] for _ in range(n)]
    for a, b in prereqs:
        graph[b].append(a)

    # 0 = unvisited, 1 = in progress (on current DFS path), 2 = done
    state = [0] * n

    def dfs(node):
        if state[node] == 2:
            return True  # already processed, no cycle from here
        if state[node] == 1:
            return False  # cycle detected
        state[node] = 1  # mark as in progress
        for neighbor in graph[node]:
            if not dfs(neighbor):
                return False
        state[node] = 2  # mark as done
        return True

    for i in range(n):
        if state[i] == 0:
            if not dfs(i):
                return False
    return True

