def can_finish(n, prereqs):
    # Build adjacency list: course -> list of courses that depend on it
    # Actually, prereqs[i] = [course, prerequisite] means course depends on prerequisite
    # Edge: prerequisite -> course
    adj = [[] for _ in range(n)]
    for course, prereq in prereqs:
        adj[prereq].append(course)

    # 0 = unvisited, 1 = in progress (on recursion stack), 2 = done
    state = [0] * n

    def dfs(node):
        if state[node] == 2:
            return False  # already processed, no cycle from here
        if state[node] == 1:
            return True  # found a cycle
        state[node] = 1  # mark as in progress
        for neighbor in adj[node]:
            if dfs(neighbor):
                return True  # cycle found downstream
        state[node] = 2  # mark as done
        return False  # no cycle from this node

    for i in range(n):
        if state[i] == 0:
            if dfs(i):
                return False  # cycle detected, cannot finish

    return True  # no cycles, can finish all courses

