def count(grid):
    if not grid:
        return 0
    rows, cols = len(grid), len(grid[0])
    visited = set()

    def r(c):
        i, j = c
        return 0 <= i < rows and 0 <= j < cols and grid[i][j] == 1 and (i, j) not in visited

    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            visited.add((x, y))
            for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                if r((nx, ny)):
                    stack.append((nx, ny))

    islands = 0
    for i in range(rows):
        for j in range(cols):
            if r((i, j)):
                dfs(i, j)
                islands += 1
